package br.com.fiap.bank.plataforma;
import br.com.fiap.bank.plataforma.application.CreditoApplicationService; import br.com.fiap.bank.plataforma.application.dto.SolicitarCreditoRequest; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import java.math.BigDecimal;
@Component public class PlataformaDataInitializer implements CommandLineRunner { private final CreditoApplicationService service; public PlataformaDataInitializer(CreditoApplicationService service){this.service=service;} @Override public void run(String... args){if(!service.listar().isEmpty())return; try {service.solicitar(new SolicitarCreditoRequest("12345678900","Ana Silva","EMPRESTIMO_PESSOAL",new BigDecimal("15000.00"),24,new BigDecimal("7500.00")));service.solicitar(new SolicitarCreditoRequest("98765432100","Carlos Eduardo Oliveira","CREDITO_IMOBILIARIO",new BigDecimal("350000.00"),180,new BigDecimal("12000.00")));service.solicitar(new SolicitarCreditoRequest("55544433399","Mariana Souza","CREDITO_AUTOMOTIVO",new BigDecimal("45000.00"),48,new BigDecimal("4200.00")));}catch(Exception e){System.err.println("Carga inicial da Plataforma de Crédito não concluída: "+e.getMessage());}} }